package ir.bayad.app

import java.text.Normalizer
import java.util.Locale

enum class SafetyClass { NONE, AMBIGUOUS_EDUCATIONAL, HARMFUL_NON_IMMINENT, IMMINENT }

/** Conservative offline keyword/rule screening; not intent understanding or a complete detector. */
object LocalSafetyClassifier {
    fun normalize(input: String): String {
        val digits = mapOf('۰' to '0', '۱' to '1', '۲' to '2', '۳' to '3', '۴' to '4', '۵' to '5', '۶' to '6', '۷' to '7', '۸' to '8', '۹' to '9', '٠' to '0', '١' to '1', '٢' to '2', '٣' to '3', '٤' to '4', '٥' to '5', '٦' to '6', '٧' to '7', '٨' to '8', '٩' to '9')
        return Normalizer.normalize(input.lowercase(Locale.ROOT), Normalizer.Form.NFKC)
            .replace('ي','ی').replace('ى','ی').replace('ك','ک').replace('ۀ','ه').replace('ة','ه').replace('ؤ','و').replace('إ','ا').replace('أ','ا').replace('ٱ','ا')
            .replace("ـ", "").map { digits[it] ?: it }
            .replace(Regex("[\u064B-\u065F\u0670]"), "")
            .replace(Regex("""[\u200c\u200d\u200e\u200f\u202a-\u202e\s]+"""), " ")
            .replace(Regex("""[^\p{L}\p{N} ]+"""), " ").replace(Regex("""\s+"""), " ").trim()
    }
    private val harm = listOf("قتل", "بکشم", "کشتن", "آسیب زدن", "چاقو بزن", "تیراندازی", "تجاوز", "به زور رابطه", "رابطه اجباری", "وادار به رابطه", "آزار جنسی", "سرقت", "دزدی", "زورگیری", "کیف قاپی", "جیب بری", "کلاهبرداری", "فیشینگ", "جعل", "اختلاس", "باجگیری", "تهدید", "کتک زدن", "خشونت", "اذیتش کنم", "آزارش", "تعقیبش", "آبرویش را ببرم", "اطلاعاتش را پخش", "آدرسش را منتشر", "دکسینگ", "قاچاق مواد", "فروش مواد", "مواد مخدر بفروشم", "وادار به مصرف")
    private val imminent = listOf("همین الان", "الان میخوام", "الان می خواهم", "امشب میخوام", "الان قصد دارم", "قصد دارم همین", "چاقو دستمه", "سلاح دستمه", "اسلحه دستمه", "سلاح دارم", "اسلحه دارم", "تهدیدش کردم", "میخوام بکشم", "میخواهم بکشم", "میخوام بهش تجاوز", "میخواهم به او تجاوز", "الان به او آسیب")
    private val educational = listOf("تحقیق", "برای مدرسه", "داستان", "رمان", "تاریخچه", "خبر", "گزارش", "پیشگیری", "آموزش ایمنی", "آگاهی بخشی", "قربانی", "مستند")
    private val explicitIntent = listOf("میخوام", "می خواهم", "میخواهم", "قصد دارم", "برنامه دارم", "چطور انجام بدم", "راهش چیه", "کمکم کن", "میخوام انجامش", "میخواهم انجامش", "میخوام به", "میخواهم به")

    fun classify(input: String): SafetyClass {
        val n = normalize(input)
        if (n.isBlank()) return SafetyClass.NONE
        val hasHarm = harm.any { normalize(it) in n }
        if (imminent.any { normalize(it) in n } && (hasHarm || listOf("بزنم", "آسیب", "حمله").any { normalize(it) in n })) return SafetyClass.IMMINENT
        if (!hasHarm) return SafetyClass.NONE
        if (educational.any { normalize(it) in n } && explicitIntent.none { normalize(it) in n }) return SafetyClass.AMBIGUOUS_EDUCATIONAL
        return SafetyClass.HARMFUL_NON_IMMINENT
    }
}

object LocalPlanner {
    fun create(goal: String): Pair<List<Step>, Boolean> {
        val kind = LocalSafetyClassifier.classify(goal)
        if (kind == SafetyClass.IMMINENT || kind == SafetyClass.HARMFUL_NON_IMMINENT) return safeSteps(kind, goal) to true
        val n = LocalSafetyClassifier.normalize(goal); val g = goal.trim()
        val templates = when {
            listOf("آب", "آبرسانی", "هیدرات").any { it in n } -> listOf("الگوی امروزت را ببین" to "چه زمان‌هایی نوشیدن آب یادت می‌رود؟ یک روز بدون قضاوت بررسی کن.", "یک نشانه‌ی ساده انتخاب کن" to "مثلاً بعد از بیدارشدن یا کنار هر وعده.", "دسترسی را آسان کن" to "یک لیوان تمیز در جای دیدنی بگذار.", "یادآور ملایم تنظیم کن" to "نیاز افراد متفاوت است؛ راهی متناسب با خودت انتخاب کن.", "پایان روز مرور کن" to "ببین چه چیزی کمک کرد و فردا چه تغییری می‌خواهی.")
            listOf("درس", "مطالعه", "امتحان", "کنکور", "یادگیری", "زبان").any { it in n } -> listOf("موضوع را کوچک کن" to "یک مبحث مشخص برای نوبت اول انتخاب کن.", "زمان کوتاه رزرو کن" to "یک بازه‌ی کوتاه و واقع‌بینانه برای امروز بگذار.", "محیط را آماده کن" to "منبع لازم را باز کن و حواس‌پرتی‌های غیرضروری را کنار بگذار.", "با بازیابی تمرین کن" to "پس از مطالعه نکته‌ها را بدون نگاه‌کردن به منبع به یاد بیاور.", "مرور و تنظیم" to "آنچه یاد گرفتی ثبت کن و نوبت بعد را متناسب با انرژی‌ات بچین.")
            listOf("پس انداز", "پول", "هزینه", "خرید", "درآمد", "بودجه", "سرمایه").any { it in n } -> listOf("هدفت را روشن کن" to "محدوده‌ی زمانی را با شرایط خودت مشخص کن.", "وضعیت فعلی را ببین" to "درآمد و هزینه‌های ضروری را بدون سرزنش مرور کن.", "یک هزینه‌ی قابل‌تغییر بیاب" to "فقط چیزی را انتخاب کن که به نیازهای ضروری آسیب نزند.", "گام کوچک را انتخاب کن" to "اگر ممکن است مبلغی متناسب با توانت کنار بگذار.", "هفتگی بازبینی کن" to "پیشرفت و شرایط تازه را بسنج و برنامه را تنظیم کن.")
            else -> listOf("تصویر روشن بساز" to "موفقیت در «$g» برای تو دقیقاً چه شکلی دارد؟ یک جمله بنویس.", "گام اول را کوچک کن" to "کاری را انتخاب کن که در کمتر از ۲۰ دقیقه بتوانی شروعش کنی.", "زمان و جای شروع را تعیین کن" to "برای قدم بعدی یک زمان و مکان واقع‌بینانه انتخاب کن.", "مانع احتمالی را پیش‌بینی کن" to "یک مانع را نام ببر و برایش راه‌حل ساده آماده کن.", "پیشرفت را مرور کن" to "بعد از انجام قدم نتیجه را ببین و ادامه‌ی مسیر را تنظیم کن.")
        }
        return templates.map { Step(it.first, it.second) } to false
    }
    private fun safeSteps(kind: SafetyClass, goal: String): List<Step> {
        val immediate = kind == SafetyClass.IMMINENT
        val opening = if (immediate) listOf(
            Step("همین حالا فاصله بگیر", "به سمت هیچ‌کس نرو و تماس نگیر. بدون ایجاد خطر از موقعیت فاصله بگیر و به مکانی عمومی یا زیرنظر فرد امن برو."),
            Step("خطر را بیشتر نکن", "وسیله‌ی خطرناک را فقط اگر کاملاً بی‌خطر است زمین بگذار یا به فرد امن بسپار؛ برای برداشتن یا جابه‌جایی آن خطر نکن."),
            Step("کمک فوری بخواه", "با فرد مورداعتماد تماس بگیر و تنها نمان. اگر در ایران خطر فوری است، بسته به نیاز با 110 پلیس، 115 فوریت پزشکی یا 123 اورژانس اجتماعی تماس بگیر. برای حمایت اجتماعی/روانی غیر فوری، 1480 را بررسی کن. شماره‌ها و دسترس‌پذیری محلی ممکن است تغییر کند.")
        ) else listOf(
            Step("فعلاً اقدام نکن", "این برنامه برای آسیب، اجبار، جرم یا دورزدن رضایت، راهنمایی عملی نمی‌سازد. به فرد موردنظر نزدیک نشو یا تماس نگیر و از موقعیت فاصله بگیر."),
            Step("با فرد امن صحبت کن", "نیاز فوری‌ات را بدون جزئیات عملیاتی با فرد مورداعتماد در میان بگذار؛ اگر احتمال خطر فوری هست تنها نمان و از خدمات اضطراری محل کمک بگیر."),
            Step("امنیت و اختیار را مقدم بدان", "به مکانی عمومی یا زیرنظر فرد امن برو. وسیله‌ی خطرناک را فقط اگر بی‌خطر است به فرد امن بسپار؛ خودت برای جابه‌جایی آن خطر نکن.")
        )
        val n = LocalSafetyClassifier.normalize(goal)
        val alternative = when {
            listOf("سرقت", "دزدی", "کلاهبرداری", "قاچاق", "درآمد").any { LocalSafetyClassifier.normalize(it) in n } -> "جایگزین قانونی: برای درآمد سراغ کاریابی، آموزش مهارت یا حمایت‌های مجاز و در دسترس برو؛ برنامه‌ی جرم یا فریب ارائه نمی‌شود."
            listOf("تجاوز", "اجباری", "آزار جنسی").any { LocalSafetyClassifier.normalize(it) in n } -> "جایگزین امن: فقط ارتباط محترمانه و رضایت روشن، آزادانه و قابل‌پس‌گرفتن؛ در نبود رضایت، فاصله بگیر و تماس را متوقف کن."
            listOf("تهدید", "تعقیب", "آبرو", "آزار", "دکسینگ").any { LocalSafetyClassifier.normalize(it) in n } -> "جایگزین قانونی: اطلاعات خصوصی منتشر نکن؛ از گفت‌وگوی امن، میانجی‌گری مناسب یا مسیر گزارش رسمی استفاده کن."
            else -> "جایگزین بی‌خطر: برای خشم یا تعارض مکث کن، از موقعیت فاصله بگیر و از فرد مورداعتماد یا حمایت حرفه‌ای کمک بگیر."
        }
        return opening + Step("یک جایگزین قانونی و امن", alternative)
    }
}
